SELECT 
FROM (
    SELECT ,
           ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY id ASC) AS rn
    FROM trade_order_item
    WHERE order_id IN

        #{orderId,jdbcType=BIGINT}

) preview
WHERE preview.rn <= #{previewLimit,jdbcType=INTEGER}
ORDER BY preview.order_id, preview.id ASC

